const uint32_t* Picture(uint16_t model, int& w, int& h) {
    switch (model) {
        case 105: w = 175, h = 368; return kFam1;
        case 106: w = 98, h = 284; return kFam2;
        case 107: w = 108, h = 275; return kFam3;
        default: return nullptr;
    }
}

